import React, { useState } from "react";
import AdoptionSearchBar from "./components/AdoptionSearchBar/AdoptionSearchBar";
import AdoptionCard from "./components/AdoptionCard/AdoptionCard";

const App = () => {
  const [searchTerm, setSearchTerm] = useState("");

  const animals = [
    {
      id: 1,
      image: "https://via.placeholder.com/250",
      name: "Bella",
      details: "Friendly and playful dog",
      place: "New York Shelter",
    },
    {
      id: 2,
      image: "https://via.placeholder.com/250",
      name: "Charlie",
      details: "Loves cuddles and walks",
      place: "California Shelter",
    },
    {
      id: 3,
      image: "https://via.placeholder.com/250",
      name: "Luna",
      details: "Calm and affectionate cat",
      place: "Florida Shelter",
    },
    {
      id: 4,
      image: "https://via.placeholder.com/250",
      name: "Max",
      details: "Energetic and loyal dog",
      place: "Texas Shelter",
    },
    {
      id: 5,
      image: "https://via.placeholder.com/250",
      name: "Daisy",
      details: "Sweet and gentle rabbit",
      place: "Nevada Shelter",
    },
  ];

  // تصفية الحيوانات بناءً على searchTerm
  const filteredAnimals = animals.filter((animal) =>
    animal.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSearch = (event) => {
    setSearchTerm(event.target.value);
  };

  return (
    <div className="container">
      <div className="search-bar">
        {/* تمرير searchTerm و handleSearch إلى AdoptionSearchBar */}
        <AdoptionSearchBar
          searchTerm={searchTerm}
          handleSearch={handleSearch}
        />
      </div>
      <div className="row">
        {filteredAnimals.map((animal) => (
          <div key={animal.id} className="col">
            <AdoptionCard
              image={animal.image}
              name={animal.name}
              details={animal.details}
              place={animal.place}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;
